        alignItems: 'center',
        justifyContent: 'center',
        backgroundColor: '#f0f4f9',
        borderRadius: '6px',
        padding: '8px',
        color: '#5E6AD2'
      },
      iconText: {
        fontSize: '16px'
      },
      titleContainer: {
        flex: 1,
        minWidth: 0
      },
      title: {
        fontWeight: '600',
        fontSize: '16px',
        color: '#1e293b',
        marginBottom: '4px',
        wordBreak: 'break-word'
      },
      subtitle: {
        fontSize: '14px',
        color: '#64748b',
        marginBottom: '2px'
      },
      identifier: {
        fontSize: '14px',
        color: '#64748b'
      },
      externalLink: {
        color: '#64748b',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        marginLeft: '8px',
        textDecoration: 'none'
      },
      linkText: {
        fontSize: '16px'
      },
      container: {
        display: 'flex',
        flexWrap: 'wrap',
        gap: '16px',
        justifyContent: 'flex-start',
        width: '100%'
      }
    };

    return React.createElement('div', { key: issue.id, style: styles.card },
      React.createElement('div', { style: styles.header },
        React.createElement('div', { style: styles.iconContainer },
          React.createElement('span', { style: styles.iconText }, '🔄')
        ),
        React.createElement('div', { style: styles.titleContainer },
          React.createElement('div', { style: styles.title }, issue.title),
          React.createElement('div', { style: styles.subtitle }, subtitle),
          React.createElement('div', { style: styles.identifier }, issue.identifier)
        ),
        issue.team_key && issue.identifier && React.createElement('a', { 
          href: `https://linear.app/${issue.team_key}/issue/${issue.identifier}`, 
          target: '_blank', 
          rel: 'noopener noreferrer',
          style: styles.externalLink
        }, React.createElement('span', { style: styles.linkText }, '🔗'))
      )
    );
  };

  // If it's a single issue
  if (isSingleIssue) {
    return renderIssueCard(data);
  }

  // If it's a list of issues
  const styles = {
    container: {
      display: 'flex',
      flexWrap: 'wrap',
      gap: '16px',
      justifyContent: 'flex-start',
      width: '100%'
    }
  };

  return React.createElement('div', { style: styles.container },
    data.items.map(issue => renderIssueCard(issue))
  );
